const http = (options) => this.helpers.httpRequest(options);

async function serviceToken() {
  const body = `grant_type=client_credentials&client_id=salon-agent&client_secret=${encodeURIComponent($env.SALON_AGENT_SECRET)}`;
  const { access_token } = await http({
    method: 'POST',
    url: $env.KEYCLOAK_TOKEN_URL,
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body,
    json: true,
  });
  return access_token;
}

async function graphql(url, token, query, variables = {}) {
  const response = await http({
    method: 'POST',
    url,
    headers: { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' },
    body: { query, variables },
    json: true,
  });
  if (response.errors?.length) throw new Error(response.errors[0].message);
  return response.data;
}

// Se envía solo con WhatsApp configurado, con teléfono y con la autorización del cliente
function whatsappItem(phone, text, template, parameters = []) {
  const to = String(phone ?? '').replace(/\D/g, '');
  if (!$env.WHATSAPP_TOKEN || !to) return [];
  // Meta solo admite texto libre dentro de una conversación abierta: lo demás requiere una plantilla aprobada
  const message = template
    ? { type: 'template', template: { name: template, language: { code: 'es' }, components: [{ type: 'body', parameters: parameters.map((value) => ({ type: 'text', text: String(value) })) }] } }
    : { type: 'text', text: { body: text } };
  return [{ json: { payload: { messaging_product: 'whatsapp', to, ...message } } }];
}

async function clientContact(token, clientId) {
  const { getClientById } = await graphql($env.CRM_GRAPHQL_URL, token, 'query ($id: ID!) { getClientById(id: $id) { fullName phone whatsappOptIn } }', { id: clientId });
  return getClientById;
}

const event = $input.first().json;
const contact = await clientContact(await serviceToken(), event.clientId);
if (!contact?.whatsappOptIn) return [];
const name = contact.fullName.split(' ')[0];
return whatsappItem(
  contact.phone,
  `¡Hola ${name}! Tu reserva de ${event.serviceName} está confirmada y pagada. Puedes ver tu cita y tu factura en ${$env.PORTAL_URL}.`,
  $env.WHATSAPP_TEMPLATE_CONFIRMACION,
  [name, event.serviceName],
);
